#endif
            state->have = 0;
            state->mode = LENLENS;
	    /* fall through */
        case LENLENS:
            while (state->have < state->ncode) {
                NEEDBITS(3);
                state->lens[order[state->have++]] = (unsigned short)BITS(3);
                DROPBITS(3);
